test-code.code:
class Bad {
    companion object {
        var count: Int = 0 // bad: mutable static, not thread-safe
    }
}

object Counter {
    var count: Int = 0 // bad
}

class Cache {
    companion object {
        var items: MutableList<String> = mutableListOf() // bad
    }
}

class Good {
    companion object {
        val MAX: Int = 100 // ok: immutable
        val ITEMS: List<String> = listOf("a", "b") // ok: immutable
    }
}

class GoodVolatile {
    companion object {
        @Volatile
        var running: Boolean = false // ok: volatile
    }
}

class GoodLocal {
    fun doWork() {
        var count = 0 // ok: local variable, not shared
        count++
    }
}

class GoodLambda {
    fun process(items: List<String>): List<Int> =
        items.map {
            var len = it.length // ok: local to lambda
            len
        }
}
